window.initPowerGridLayer = function(map) {
    var layerGroup = L.layerGroup();
    
    if (!window.AP_POWER_GRID_GEOJSON || !window.AP_POWER_GRID_GEOJSON.features) {
        return layerGroup;
    }
    
    L.geoJSON(window.AP_POWER_GRID_GEOJSON, {
        style: function(feature) {
            var v = feature.properties.voltage_val || 33000;
            var isEHT = (v >= 132000);
            return {
                color: isEHT ? '#ef4444' : '#f59e0b',
                weight: isEHT ? 3.5 : 2.2,
                opacity: 0.9,
                dashArray: isEHT ? null : '4 3'
            };
        },
        pointToLayer: function(feature, latlng) {
            return L.circleMarker(latlng, {
                radius: 6,
                fillColor: '#ef4444',
                color: '#ffffff',
                weight: 2,
                opacity: 1,
                fillOpacity: 0.95
            });
        },
        onEachFeature: function(feature, layer) {
            var p = feature.properties;
            if (feature.geometry.type === 'Point') {
                layer.bindTooltip(`
                    <div style="font-family: Inter, sans-serif; min-width: 170px;">
                        <div style="font-weight: 800; color: #ef4444; font-size: 12px;"><i class="fas fa-bolt"></i> ${p.name}</div>
                        <div style="font-size: 10.5px; color: #0f172a; margin-top: 2px;"><strong>Voltage Rating:</strong> ${p.voltage}</div>
                        <div style="font-size: 10px; color: #64748b;"><strong>Utility:</strong> ${p.operator}</div>
                    </div>
                `, { direction: 'top', offset: [0, -6] });
            } else {
                layer.bindTooltip(`
                    <div style="font-family: Inter, sans-serif; min-width: 180px;">
                        <div style="font-weight: 800; color: #f59e0b; font-size: 12px;"><i class="fas fa-bolt"></i> ${p.name}</div>
                        <div style="font-size: 10.5px; color: #0f172a; margin-top: 2px;"><strong>Transmission Voltage:</strong> ${p.voltage}</div>
                        <div style="font-size: 10px; color: #475569;"><strong>Grid Authority:</strong> ${p.operator}</div>
                        <div style="font-size: 9.5px; color: #64748b;"><strong>Grid Zone:</strong> ${p.grid_zone}</div>
                    </div>
                `, { direction: 'top', offset: [0, -6] });
            }
        }
    }).addTo(layerGroup);
    
    return layerGroup;
};
